INSERT INTO `menu` (`id`, `titre`, `description`, `nombre_personne_min`, `prix_par_personne`, `quantite_restante`, `entree_id`, `plat_principal_id`, `dessert_id`, `image_name`, `delai`, `stockage`) VALUES
	(1, 'L\'escale iodée', 'Pavé de bar sauvage rôti sur la peau et son riz noir vénéré aux agrumes.', 2, 45, 6, 9, 4, 12, 'Pave_de_bar_sauvage.jpg', NULL, NULL),
	(2, 'La signature volaille', 'Suprême de poulet fermier aux morilles et risotto crémeux au parmesan.', 2, 35, 5, 10, 2, 12, 'Supreme_de_poulet_fermier.jpg', NULL, NULL),
	(3, 'L\'héritage Terroir', 'Cœur de filet de bœuf braisé, riz safrané et réduction de jus de viande corsé.', 2, 40, 3, 9, 3, 13, 'Coeur_de_filet_de_boeuf.jpg', NULL, NULL),
	(4, 'Linguine à la Truffe', 'Pâtes fraîches artisanales sublimées par une crème de truffe noire d\'été.', 2, 22, 2, 9, 6, 12, 'Pates_fraiche_artisanales.jpg', NULL, NULL),
	(5, 'Ramen aux Crevettes', 'Bouillon de crustacés parfumé à la citronnelle et au gingembre.', 1, 26, 0, 8, 7, 12, 'Bouillon_de_crustaces.jpg', NULL, NULL),
	(6, 'L\'horizon aquatique', 'Duo de dorade et gambas royales sur lit de riz sauvage aux petits légumes.', 4, 35, 3, 9, 5, 13, 'Duo_de_daurade_et_gambas.jpg', NULL, NULL);
