INSERT INTO `plat` (`id`, `nom`, `image`, `description`) VALUES
	(2, 'Suprême de poulet fermier', 'Supreme_de_poulet_fermier.jpg', 'Aux morilles et risotto crémeux au parmesan'),
	(3, 'Coeur de filet de boeuf', 'Coeur_de_filet_de_boeuf.jpg', 'Braisé, riz safrané et réduction de jus de viande corsé'),
	(4, 'Pavé de bar sauvage', 'Pave_de_bar_sauvage.jpg', 'Rôti sur la peau et son riz noir vénéré aux agrumes'),
	(5, 'Duo de dorade et gambas', 'Duo_de_daurade_et_gambas.jpg', 'Royales sur lit de riz sauvage aux petits légumes.'),
	(6, 'Pâtes fraîches artisanales', 'Pates_fraiche_artisanales.jpg', 'Sublimées par une crème de truffe noire d\'été.'),
	(7, 'Bouillon de crustacés', 'Bouillon_de_crustaces.jpg', 'Parfumé à la citronnelle et au gingembre, servi avec des crevettes.'),
	(8, 'Carpaccio de Saint-Jacques', NULL, 'Fines lamelles de noix de Saint-Jacques, zestes de citron vert et baies roses.'),
	(9, 'Velouté de Potimarron', NULL, 'Crème onctueuse au potimarron rôti, éclats de châtaignes et huile de truffe.'),
	(10, 'Tartare d\'Avocat et Crevettes', NULL, 'Avocat fondant, crevettes marinées au gingembre et coriandre fraîche.'),
	(11, 'Dôme Chocolat Noir', NULL, 'Cœur fondant au caramel beurre salé sur un sablé croquant au cacao.'),
